"""Os 72 dons dos doze aspectos, adaptados em português da fonte p.309–319."""
def ampliar(d):
    def dom(id,nome,aspecto,tipo,pagina,texto,resumo,requisito=''):
        d['equipamentos'].append({'id':'dom-reliquia-'+id,'nome':nome,'fonte':'gm-core','pagina':pagina,'nivel':{'menor':1,'maior':9,'grandioso':17}[tipo],'categoria':'dom-reliquia','aspecto':aspecto,'categoriaDom':tipo,'requisitos':requisito,'precoPo':None,'preco':'Dom concedido por história; não vendido','raridade':'incomum','somenteMestre':True,'uso':'Relíquia do aspecto '+aspecto,'descricao':texto+'\n\nCD de salvaguarda é a maior CD de classe ou magia do portador; ataque de magia é essa CD menos 10. O nível usado no escalonamento é o da relíquia, igual ao do dono. A concessão e o nível recomendado dependem do mestre.','resumo':[resumo],'automatizavel':False,'automacao':'consulta','mecanica':{'versao':1,'tipo':'dom-reliquia','estado':'pendente-executor','motivo':'A execução exige concessão do mestre, escalonamento, requisitos e gatilhos individuais; consultar descrição não concede efeito automático.'}})
    dom('faisca-mortal','Faísca mortal','ar','menor',309,'Duas ações, concentração e manuseio. Alvo criatura a até 6 m: 1d12 de eletricidade com Reflexos básico. Acrescente 1d12 no nível 6 e novamente a cada quatro níveis.','Descarga elétrica a 6 m; escala em dados com Reflexos básico.')
    dom('passos-pluma','Passos de pluma','ar','menor',310,'Enquanto vestir a relíquia, não dispara armadilhas acionadas por peso ou placas de pressão. Dano de queda diminui pelo nível da relíquia; se chegar a 0, aterrissa em pé. +1 de item a Atletismo para Saltar; aumenta para +2 no nível 9 e +3 no 17.','Evita gatilhos de peso, reduz quedas e melhora saltos.','Relíquia vestida')
    dom('barreira-vento','Barreira de vento','ar','menor',310,'Uma ação de concentração: +2 de circunstância à CA contra ataques à distância até início de seu próximo turno. A partir do nível 13, +3.','Uma ação protege contra ataques à distância até seu próximo turno.')
    dom('tempestade-raios','Tempestade de raios','ar','maior',310,'Duas ações de concentração criam emanação de 9 m de vento, chuva e relâmpagos. É terreno difícil para todos exceto você. Quem entrar ou começar turno nela sofre 1d12 elétrico, Reflexos básico; 2d12 no nível 15. Sustentar por até um minuto.','Emanação dificulta terreno e causa eletricidade ao entrar ou começar turno.')
    dom('ventos-propulsores','Ventos propulsores','ar','maior',310,'Duas ações, concentração e manuseio, uma vez por hora: conjura Voar em você, seguindo duração e limitações da magia.','Conjura Voar em si uma vez por hora.')
    dom('tempestade-viva','Tempestade viva','ar','grandioso',310,'Voo igual ao seu deslocamento ou 18 m, o maior. Criatura que acerta você com ataque corpo a corpo sofre 5 elétrico. Pode conjurar Relâmpago de 5º círculo como magia inata, usando sua regra de conjuração.','Voo permanente, retaliação elétrica e Relâmpago inato.')
    dom('sentidos-fera','Sentidos da fera','fera','menor',310,'Vestida, concede visão na penumbra; se já possuía, visão no escuro. No nível 10 também concede faro impreciso a 3 m.','Melhora visão e concede faro no nível 10.','Relíquia vestida')
    dom('chamado-selvagem','Chamado selvagem','fera','menor',310,'Duas ações, concentração e manuseio, uma vez por dia: Invocar Animal de círculo igual à metade do nível arredondada para cima. Sustentar como a magia.','Invoca animal uma vez por dia, com círculo escalonado.')
    dom('garras-ferais','Garras ferais','fera','menor',310,'Uma ação de concentração transforma mãos em garras: ataque desarmado 1d6 cortante, ágil e acuidade. Efeito de metamorfose dura até Dispensar.','Garras ágeis de 1d6 cortante até Dispensar.','Relíquia vestida')
    dom('forma-furia','Forma de fúria','fera','maior',310,'Duas ações de concentração, duas vezes por dia: Forma Animal, círculo metade do nível arredondado para baixo. Escolha tipo de animal ao obter o dom; permanece o mesmo a cada uso.','Forma Animal duas vezes por dia, com forma escolhida na concessão.','Relíquia vestida')
    dom('trilha-fera','Trilha da fera','fera','maior',310,'Mestre escolhe ao conceder: +3 m de estado ao deslocamento terrestre, escalada igual ao terrestre ou natação igual ao terrestre. Não concede os três benefícios ao mesmo tempo.','Uma opção fixa melhora deslocamento, escalada ou natação.')
    dom('forma-vinganca','Forma de vingança','fera','grandioso',310,'Ao usar Forma de Fúria, pode conjurar Forma Aérea ou Forma de Dinossauro em vez de Forma Animal, no mesmo círculo. Cada magia tem um tipo de animal fixo: três formas totais. Enquanto transformado, Sustentar troca entre essas formas sem renovar duração.','Amplia Forma de Fúria para três formas alternáveis.','Dom Forma de fúria')
    dom('retribuicao-divina','Retribuição divina','celestial','menor',310,'Duas ações de concentração, traço sagrado: faça Golpe contra inimigo que danificou você ou aliado na última rodada. Acerto acrescenta um dado de dano da arma. Alvo profano fica enfraquecido 1 até início de seu próximo turno, ou 2 no crítico.','Golpe retaliatório acrescenta um dado e enfraquece alvo profano.','Relíquia arma')
    dom('graca-ceus','Graça dos céus','celestial','menor',311,'Vestida, +1 de estado à CA contra ínferos e resistência a uma energia correspondente à origem celestial, por exemplo sônico de anjo coral. Resistência metade do nível, mínimo 1; tipo definido pela origem, não alterado a cada ataque.','Defesa contra ínferos e resistência à energia de sua origem.','Relíquia vestida')
    dom('palavra-fe','Palavra de fé','celestial','menor',311,'Duas ações, concentração e manuseio, uma vez por hora. Toque em si ou aliado: recupera 1d8 PV por nível e reduz assustado em 1. Traços cura, sagrado e vitalidade; respeite efeitos sobre criaturas com cura por vazio.','Cura por toque uma vez por hora e reduz assustado.')
    dom('chamado-justo','Chamado justo','celestial','maior',311,'Duas ações, concentração e manuseio, uma vez por dia. Durante um minuto, suas armas e ataques desarmados recebem runa sagrada enquanto os empunhar. Se capacidade estiver cheia, escolha propriedade a ficar dormente. Golpes de aliados a até 9 m recebem traço sagrado, sem conceder toda a runa a eles.','Armas recebem runa sagrada por um minuto; aliados próximos ganham o traço.')
    dom('brilho-sagrado','Brilho sagrado','celestial','maior',311,'Duas ações, concentração e manuseio, Sustentar por até um minuto. Luz brilhante em emanação de 9 m. Profanos na luz ficam assustados 1 e não podem reduzir abaixo de 1 enquanto permanecerem. Ínferos aumentam fraqueza a sagrado existente em 5; não cria fraqueza onde não houver.','Luz mantém medo em profanos e aumenta fraqueza existente dos ínferos.')
    dom('receptaculo-angelical','Receptáculo angelical','celestial','grandioso',311,'Duas ações, concentração e manuseio, uma vez por dia. Aumenta PV atuais e máximos em 50 e concede fraqueza 10 a profano. Se possui Chamado Justo, recebe seus efeitos sem gastar uso diário. Pode Dispensar e, ao fazê-lo, liberar Decreto Divino de 8º círculo com traço sagrado. A fonte não fornece duração fixa além de poder Dispensar; não invente limite.','Encarnação celestial aumenta PV, com fraqueza profana e decreto ao Dispensar.')
    dom('olhar-morte','Olhar da morte','morte','menor',312,'Duas ações, concentração e manuseio. Criatura visível a até 9 m sofre 1d6 de vazio por dois níveis, mínimo 1d6, com Fortitude básico. Alvo com cura por vazio em vez disso recupera 1d6 PV por nível e fica temporariamente imune a esse efeito por dez minutos.','Olhar causa vazio; criatura com cura por vazio recebe cura e imunidade temporária.')
    dom('morte-viva','Morte viva','morte','menor',312,'Somente se for vivo: resultado de salvaguarda contra efeito que causa vazio melhora um grau. Crítico contra efeito capaz de curar mortos-vivos cura metade do dano completo da magia. Cura por vitalidade recebida tem metade do efeito normal.','Protege contra vazio, mas reduz cura por vitalidade pela metade.')
    dom('mortalha-alem','Mortalha do além','morte','menor',312,'Uma ação, concentração e manuseio, uma vez por dia; dura um minuto. Resistência a veneno metade do nível e +1 de estado em salvaguardas contra morte, doenças, paralisia, veneno e sono. CD de recuperação passa a 9 + morrendo em vez de 10 + morrendo.','Proteção breve contra aflições e CD de recuperação reduzida em 1.')
    dom('atravessar-veu','Atravessar o véu','morte','maior',312,'Empunhada ou vestida, concede cura por vazio: vitalidade prejudica e vazio cura como morto-vivo. Cura por vazio também concede resistência 5 a todo dano até início de seu próximo turno, exceto força, toque fantasma, espírito e vitalidade. +2 de item em salvaguardas contra morte; +3 a partir do nível 13.','Concede cura por vazio e resistência breve após receber esse tipo de cura.','Dom Morte viva')
    dom('mare-morte','Maré de morte','morte','maior',312,'Pode ativar Olhar da Morte com três ações para atingir todos os vivos a até 9 m, exceto você. Se possui cura por vazio, pode incluir-se para curar. Preserve salvaguarda, dano e imunidade temporária de Olhar da Morte.','Olhar da Morte com três ações torna-se área.','Dom Olhar da morte')
    dom('espectro-sombrio','Espectro sombrio','morte','grandioso',312,'Duas ações de concentração, uma vez por dia; Sustentar por até um minuto. Torna-se incorpóreo: imune a efeitos que precisam de corpo, inclusive precisão e exposição à maioria das doenças e venenos. Resistência a todo dano metade do nível, dobrada contra dano não mágico; força, toque fantasma, espírito, vazio e vitalidade ignoram. Pode atravessar sólidos, mas dentro deles não percebe, ataca nem Interage com exterior e começa turno lento 1. Corpóreos atravessam seu espaço, sem terminar nele. Não pode fazer testes de Força contra corpóreos ou objetos, salvo objetos toque fantasma; corpóreos também não podem fazê-los contra você.','Incorporeidade sustentada protege e atravessa sólidos, com limitações de interação.')
    dom('aliviar-fardo','Aliviar o fardo','terra','menor',312,'Com a relíquia consigo e de pé no chão: +1 Volume antes de sobrecarregado e +2 ao Volume máximo. No nível 6 e a cada quatro depois, aumente esses benefícios em +1 e +2, respectivamente.','Aumenta capacidade de carga enquanto estiver no chão.')
    dom('geodo-rolante','Geodo rolante','terra','menor',312,'Duas ações de concentração, uma vez por hora: cria esfera em quadrado livre a 9 m. Uma ação de concentração move até 9 m no chão. Quem tiver espaço atravessado sofre 2d6 contundente com Reflexos básico, no máximo uma vez por turno. Dura até um minuto, destruição ou Dispensar. CA 5, Dureza 10, 40 PV; imune a críticos e precisão.','Esfera controlada causa dano ao atravessar criaturas, uma vez por turno.')
    dom('terra-estilhacada','Terra estilhaçada','terra','menor',313,'Duas ações, concentração e manuseio, uma vez por hora. Trecho de terra ou pedra de 3 m de raio a até 18 m torna-se terreno difícil. Entrar em quadrado durante movimento exige Acrobatismo ou Reflexos; falha sofre 1d6 perfurante, uma rolagem por ação de movimento. No nível 6 e a cada quatro posteriores, +1d6. A fonte não fixa duração: não acrescente duração inventada.','Terreno difícil perfurante com verificação por ação de movimento.')
    dom('erguer-muralhas','Erguer muralhas','terra','maior',313,'Três ações, concentração e manuseio, uma vez por dia: Muralha de Pedra de 5º círculo. Use construção, duração e resistência da magia.','Conjura Muralha de Pedra uma vez por dia.')
    dom('riqueza-subterranea','Riqueza subterrânea','terra','maior',313,'Preparação diária cria fragmento de prata, ferro frio, ouro ou pedra/metal não precioso escolhido. Se relíquia é arma, absorve imediatamente e imita material até próxima preparação. Caso contrário, Interagir toca fragmento a arma de metal/pedra, imitando material por dez minutos. Interage com fraquezas e resistências como esse material, sem criar objeto vendável. Fragmento não usado desaparece na próxima preparação. Nível 17 acrescenta adamante e prata da aurora às opções.','Fragmento diário muda como uma arma interage com resistências e fraquezas de materiais.')
    dom('estatua-viva','Estátua viva','terra','grandioso',313,'Petrificar e Passo Seguro de 6º círculo como magias inatas, cada uma diária; Passo Seguro serve apenas para remover petrificação. Enquanto estiver no chão, resistência 5 a físico exceto adamante; aumenta para 8 em cavernas ou subterrâneo.','Petrificação inata e resistência física aumentada no subterrâneo.')
    dom('ferida-amaldicoada','Ferida amaldiçoada','ínfero','menor',313,'Reação de concentração e profano quando Golpe com a relíquia danifica criatura a até 18 m. Vontade: falha impede recuperar especificamente os PV perdidos pelo Golpe até próxima preparação diária. Aplicar em criatura já afetada encerra aplicação anterior, sem acumular dívidas de dano.','Maldição impede curar dano daquele Golpe até preparação seguinte.','Relíquia arma')
    dom('desafio-infernal','Desafio infernal','ínfero','menor',313,'Vestida, +1 de estado à CA contra celestiais e resistência à energia da origem ínfera, por exemplo fogo de diabo. Resistência metade do nível, mínimo 1.','Defesa contra celestiais e energia da origem ínfera.','Relíquia vestida')
    dom('pequeno-ajudante','Pequeno ajudante','ínfero','menor',313,'Relíquia torna-se inteligente e profana, com visão precisa e audição imprecisa a 9 m. Fala e entende um idioma conhecido seu; Inteligência, Sabedoria e Carisma +0. Percepção e Vontade iguais aos seus modificadores de proficiência nessas estatísticas, não aos totais com atributos/bônus. Saber do tipo de ínfero treinado com total 2 + nível da relíquia. Ao contrário de item inteligente normal, não possui ações/reação nem ativa poderes próprios.','Desperta mente comunicativa sem conceder ações extras ao item.')
    dom('barganha-infernal','Barganha infernal','ínfero','maior',313,'Uma ação de concentração, uma vez por hora. Escolha neutralizar condição prejudicial, curar 3d8+16 PV ou +2 de estado ao ataque por um minuto. Após benefício, sorteie preço: estupefato 1 por um minuto, desajeitado 1 por um minuto, perda de 1d8 PV ou −1 ao dano por um minuto. Não permite escolher o preço favorável.','Benefício escolhido cobra um dos quatro preços aleatórios.')
    dom('fervor-profano','Fervor profano','ínfero','maior',314,'Duas ações, concentração e manuseio, uma vez por dia: durante um minuto, armas e desarmados recebem runa profana enquanto empunhados. Capacidade cheia exige pôr propriedade existente em dormência. Golpes de aliados a até 9 m recebem traço profano, sem toda a runa.','Armas ganham runa profana por um minuto; aliados próximos ganham seu traço.')
    dom('comandar-legiao','Comandar legião','ínfero','grandioso',314,'Chamar Legião: três ações de concentração, uma vez por dia; Invocar Ínfero de 6º círculo, invocando dois em vez de um e comandando ambos com uma ação de Sustentar. Se possui Fervor Profano, também recebe seus efeitos sem gastar uso diário. Por um minuto pode Reforçar Legião, ação livre de concentração quando um invocado for banido: reinvoca o mesmo adjacente, PV completos e sem condições ou efeitos. Não restaura magias ou habilidades limitadas já gastas.','Invoca dois ínferos, sustenta juntos e reinvoca banidos sem renovar poderes limitados.')
    dom('dardo-chama','Dardo de chama','fogo','menor',314,'Duas ações, concentração e manuseio; ataque de magia contra alvo a 9 m. Dano 1d6 fogo por dois níveis, mínimo 1d6; crítico dobra e acrescenta fogo persistente igual ao nível da relíquia.','Ataque de fogo escalonado; crítico acrescenta dano persistente.')
    dom('miragem-calor','Miragem de calor','fogo','menor',314,'Com a relíquia, protege de frio ambiental severo; extremo no nível 9; incrível no 17. A partir do nível 4, duas ações de concentração, uma vez por dia: calor distorce sua imagem, deixando-o ocultado por um minuto. Localização continua evidente, portanto essa ocultação não permite Esconder-se ou Esgueirar-se.','Protege do frio e concede ocultação térmica que não permite esconder-se.')
    dom('visao-incandescente','Visão incandescente','fogo','menor',314,'Duas ações de concentração, uma vez por dia: visão térmica precisa por um minuto, alcance 9 m. Detecta vivos e objetos quentes no escuro; objetos quentes bloqueiam, mesmo transparentes, como água quente.','Sentido preciso detecta calor a 9 m por um minuto.')
    dom('propulsao-jato','Propulsão a jato','fogo','maior',314,'Uma ação de concentração, uma vez por hora; por um minuto +3 m de estado ao deslocamento e voo igual ao novo deslocamento ou 6 m, o maior. Precisa terminar cada turno no chão sólido ou cai.','Mobilidade e voo breve exigem aterrissar ao fim do turno.')
    dom('onda-escaldante','Onda escaldante','fogo','maior',314,'Duas ações, concentração e manuseio: cone de 9 m, 1d10 fogo por dois níveis, Reflexos básico. Não pode reutilizar por 1d4 rodadas.','Cone de fogo escalonado com intervalo de 1d4 rodadas.')
    dom('alma-flamejante','Alma flamejante','fogo','grandioso',314,'Resistência fogo 10. Na primeira vez a cada hora que efeito de fogo lhe causar dano, também recupera 1d8 PV por círculo de neutralização do efeito, sem eliminar o dano. Reação de concentração quando criatura a 18 m recebe crítico ou falha crítica contra fogo e não chega a 0 PV: explosão de 4,5 m centrada nela causa 6d6 fogo, Reflexos básico. Você fica imune à ativação, aliados não. Se esse dano derrubar alvo principal, vira cinza, preservando equipamento. Intervalo 1d4 rodadas entre ativações.','Resiste a fogo, cura em exposição periódica e detona chamas de críticos.')
    dom('conceder-vida','Conceder vida','vida','menor',315,'Duas ações de concentração, uma vez por dia: anima objeto adjacente no nível igual à metade do nível da relíquia, com bloco apropriado. Executa uma tarefa simples não combatente fixada na ativação, sem criatividade ou novos comandos. Dura uma hora.','Anima objeto para uma tarefa simples não combatente durante uma hora.')
    dom('onda-cura','Onda de cura','vida','menor',315,'Duas ações de concentração, uma vez por hora. Você e cada vivo em cone de 4,5 m recuperam 1d4 PV por nível da relíquia. Traços cura e vitalidade; não é ataque de vitalidade contra mortos-vivos.','Cura usuário e vivos no cone uma vez por hora.')
    dom('vida-transbordante','Vida transbordante','vida','menor',315,'Bônus de item aos PV recuperados por magia de cura de vitalidade igual à metade do nível, mínimo 1. Aplica só à primeira vez que cada conjuração específica cura você, sem repetir a cada pulso da mesma magia.','Melhora a primeira cura recebida de cada conjuração de vitalidade.')
    dom('inextinguivel','Inextinguível','vida','maior',315,'Morre por morrendo 5 em vez de 4. Sucesso em salvaguarda contra morte ou vazio transforma-se em sucesso crítico; não melhora falha automaticamente.','Eleva limite de morrendo e melhora sucessos contra morte ou vazio.')
    dom('sifao-vitalidade','Sifão de vitalidade','vida','maior',315,'Reação de concentração quando aliado a 18 m recebe cura direcionada de vitalidade, sem duração, maior que seus PV faltantes. Você ou criatura voluntária adjacente recupera o excesso acima dos PV máximos do aliado. Exemplo: faltavam 5, cura 12, repassa 7. Não conta cura de área ou efeito duradouro fora do gatilho.','Redistribui excesso de cura direcionada para você ou voluntário adjacente.')
    dom('vida-eterna','Vida eterna','vida','grandioso',316,'Duas ações de concentração, uma vez por dia. Por um minuto, emanação de 3 m cura 10 PV em você vivo e aliados vivos ao fim de seu turno. Quando você ou aliado morreria por aumentar morrendo, pode Dispensar como ação livre para impedir esse aumento e morte, terminando a ativação.','Aura cura a cada turno e pode terminar para impedir morte por morrendo.')
    dom('nexo-linguistico','Nexo linguístico','mente','menor',316,'Aprende um idioma adicional escolhido a cada dois níveis, mínimo um. Retreinar um idioma concedido exige uma semana de recesso.','Concede idiomas escalonados, retreináveis em uma semana.')
    dom('recalcular','Recalcular','mente','menor',316,'Reação de concentração quando falhar ataque. +1 de circunstância ao próximo ataque contra o mesmo alvo se ocorrer antes do início de seu próximo turno. Não rerrola o ataque que falhou.','Falhar prepara o próximo ataque contra o mesmo alvo.')
    dom('repositorio-conhecimento','Repositório de conhecimento','mente','menor',316,'Enquanto carregar, treinado em três Saberes escolhidos pelo mestre pela história da relíquia. Especialista no nível 9 e mestre no 17. Não escolha novamente a cada verificação.','Três Saberes temáticos progridem até mestre.')
    dom('filtro-percepcao','Filtro de percepção','mente','maior',316,'Duas ações de concentração, uma vez por dia, duração dez minutos. Quem entrar em emanação de 36 m faz Vontade secreta e depois fica imune por um dia. Crítico: nenhum efeito. Sucesso: −2 de estado em Percepção para detectá-lo. Falha: enquanto escondido/não detectado não se torna observado automaticamente ao agir; Buscar/detectar piora um grau e sua Furtividade para escapar atenção melhora um grau. Ação hostil contra essa criatura encerra após concluída. Falha crítica mantém esse efeito mesmo após hostilidade.','Filtro mental altera detecção, com resultado específico por grau de salvaguarda.')
    dom('grito-psiquico','Grito psíquico','mente','maior',316,'Duas ações de concentração: inimigos em explosão de 6 m centrada em você sofrem 1d10 mental por dois níveis, Vontade básico. Falha crítica também fica estupefato 1 por um minuto.','Explosão mental em inimigos; falha crítica causa estupefato.')
    dom('bastiao-mental','Bastião mental','mente','grandioso',316,'Concede telepatia; se já possui, aumenta alcance em 9 m. Sempre que ficaria estupefato, reduza valor em 1. Acelerado permanentemente, mas ação adicional somente serve a Recordar Conhecimento. Não invente alcance inicial que a entrada não especifica.','Proteção mental e ação adicional exclusiva para Recordar Conhecimento.')
    dom('jardim-boticario','Jardim do boticário','planta','menor',316,'A cada noite cresce duas ervas, colhidas na preparação seguinte. Vivo que consome por Interagir cura 1d8 por dois níveis, mínimo 1d8. Três ervas no nível 9, quatro no 17. Murcham um dia após colheita, sem estoque permanente.','Produz ervas diárias de cura que expiram em um dia.')
    dom('spray-polen','Spray de pólen','planta','menor',317,'Duas ações, concentração e manuseio: cone 4,5 m causa 1d6 veneno por dois níveis, mínimo 1d6, Fortitude básico. Falha crítica também ofuscado uma rodada. Intervalo de 1d4 rodadas.','Cone de veneno com chance de ofuscar; reutilização espera 1d4 rodadas.')
    dom('brotar-aliado','Brotar aliado','planta','menor',317,'Duas ações, concentração e manuseio, uma vez por dia: Invocar Planta ou Fungo em círculo metade do nível arredondado para cima. Sustentar como a magia.','Invoca planta ou fungo uma vez por dia.')
    dom('trepadeira-agarradora','Trepadeira agarradora','planta','maior',317,'Uma ação de manuseio lança cipó a até 15 m. Faça ataque de fixar como gancho, convertendo falha crítica em falha. Ancorado, concede +1 de estado a Atletismo para Escalar e +1,5 m de estado à distância escalada em sucesso. Dura um dia ou até criar novo cipó, que faz o anterior murchar.','Cipó ancorado melhora escalada e dura até um dia.')
    dom('danca-petalas','Dança de pétalas','planta','maior',317,'Duas ações de concentração, uma vez por hora: vira enxame de folhas por um minuto ou até Dispensar. Imune a queda, resistência 5 a contundente/cortante, fraqueza 5 a área/respingo. Passa por frestas de poucos centímetros. Não ganha mente de enxame: efeitos mentais funcionam normalmente. Não fala, conjura, manuseia com mãos, ativa itens nem faz Golpes normais. A partir do nível 13, também pode ativar por reação ao cair ou sofrer dano, aplicando defesas à ocorrência que acionou.','Forma de enxame atravessa frestas e protege de queda, mas bloqueia ações normais.')
    dom('megaflora','Megaflora','planta','grandioso',317,'Duas ações, concentração e manuseio, uma vez por dia. Planta escolhida na concessão ocupa espaço livre de 3 m a até 9 m: 50 PV, fraqueza fogo 5, CA 37, Reflexos +20, Fortitude +30; dura um minuto ou até 0 PV. Flor-cadáver: ao fim de seu turno, todos exceto você em explosão 6 m fazem Fortitude ou enjoados 2, também atordoados 2 no crítico; veneno. Espinheiro: ao fim do turno, todos exceto você na mesma área sofrem 6d8 perfurante, Reflexos básico. Árvore da Vida: vivos ao alcance Interagem para colher e comer fruto, curando 2d8+5, uma vez por rodada por criatura; colher sem comer faz fruto desaparecer, traços cura e madeira.','Planta fixa oferece área de veneno, dano ou cura conforme tipo escolhido.')
    dom('escuridao-abrangente','Escuridão abrangente','sombra','menor',317,'Sua sombra funciona como recipiente de 3 Volume, acessível por Interagir. Objetos dentro não contam na carga. No nível 6 e a cada quatro depois, +1 Volume. +4 de circunstância em Furtividade para Ocultar os Objetos, salvo observador que saiba procurar na sombra. Não torna itens indetectáveis automaticamente.','Sombra armazena carga e ajuda ocultação, sem impedir descoberta absoluta.')
    dom('obscurecer','Obscurecer','sombra','menor',317,'Em penumbra dentro de sombras, pode tentar Furtividade para Esconder-se mesmo contra criatura para a qual não esteja ocultado, como quem tem visão no escuro. Continua exigindo a verificação.','Permite esconder-se nas sombras mesmo diante de visão no escuro.')
    dom('ferreiro-sombras','Ferreiro de sombras','sombra','menor',317,'Uma ação de manuseio cria arma simples, ferramenta simples ou objeto como corda/pé de cabra a partir das sombras. Some ao concluir uma única atividade, ativar novamente ou passar um minuto, o primeiro. Não cria estoque vendável ou equipamento permanente.','Cria objeto simples temporário para uma atividade.')
    dom('sombra-dancante','Sombra dançante','sombra','maior',318,'Relíquia arma; duas ações, concentração e manuseio, uma vez por hora. Escolha alvo: sombra voa até 18 m para adjacência e faz Golpe, 5d8 do tipo normalmente causado pela relíquia; crítico dobra. Usa seu bônus da relíquia e sua penalidade por ataques múltiplos, contribuindo nela. Uma ação de ataque/concentração comanda outro Golpe contra mesmo alvo. Dura até alvo cair a 0 PV, distar mais de 120 m ou entrar onde não possa haver sombra, inclusive escuridão total. Segue alvo, não ocupa espaço, flanqueia ou vira criatura; talentos e magias que afetam armas não se aplicam.','Sombra persegue um alvo e ataca usando sua MAP, sem contar como criatura.','Relíquia arma')
    dom('estradas-escuras','Estradas escuras','sombra','maior',318,'Duas ações de concentração: teleporta você e itens vestidos/empunhados a espaço livre visível a 9 m, ou 18 m se destino não estiver em luz brilhante. Intervalo de 1d4 rodadas. Falha se levar outra criatura, mesmo transportada em recipiente extradimensional.','Teleporte curto ganha alcance em sombras, sem transportar criaturas.')
    dom('corpo-umbral','Corpo umbral','sombra','grandioso',318,'Duas ações, concentração e manuseio: Explosão de Sombras de 6º círculo, escolhendo somente contundente, cortante ou perfurante. Intervalo de 1d4 rodadas. Preserve áreas e salvaguardas da magia.','Explosão de Sombras restrita a dano físico, com espera de 1d4 rodadas.')
    dom('correntes-chicoteantes','Correntes chicoteantes','água','menor',318,'Relíquia arma. Interagir muda empunhadura para Golpes de corrente: 1d4 contundente, desarmar, acuidade, alcance 3 m, derrubar e versátil cortante; grupo mangual. Recebe fundamentais e propriedades aplicáveis da relíquia, sem aplicar propriedade incompatível. Outro Interagir retorna à empunhadura normal.','Modo de corrente concede alcance e manobras, conservando runas compatíveis.','Relíquia arma')
    dom('cortina-moncao','Cortina de monção','água','menor',318,'Três ações de concentração, uma vez por dia. Parede vertical a até 36 m, espessura 1,5 m, comprimento 9 m, altura até 9 m, caminho moldável; um minuto. Fogo que atravessa piora ataque um grau ou melhora salvaguarda dos alvos um grau. Quem tem fraqueza a água sofre valor da fraqueza ao atravessar ou começar turno na parede. −2 de estado a Percepção para perceber criatura/objeto do outro lado.','Parede de chuva enfraquece fogo, aciona fraqueza a água e dificulta percepção.')
    dom('impacto-mare','Impacto da maré','água','menor',319,'Duas ações de concentração, uma vez por dia; ataque de magia a 9 m. Sucesso causa 2d10 contundente e 2 de respingo contundente. No nível 3 e a cada dois depois, +1d10 inicial e +1 respingo. A entrada só especifica sucesso; aplique regras gerais do ataque e respingo sem inventar efeito extra de crítico.','Ataque aquático com dano e respingo crescentes.')
    dom('reservatorio-sem-fundo','Reservatório sem fundo','água','maior',319,'Extrair Água: uma ação de manuseio absorve 3,8 litros ao tocar corpo d’água adjacente ou libera essa quantidade armazenada. Pode gastar outra ação para absorver criatura inteiramente aquática tocada, causando 1d6 por nível com Fortitude básico. Escudo Líquido: reação de manuseio quando alvo de ácido/água, tenta neutralizar consumindo 3,8 litros. Mestre pode permitir outros líquidos como sangue. Estoque deve ser registrado: reservatório ilimitado não significa preenchido infinitamente.','Armazena água e gasta volume real para neutralizar líquidos.')
    dom('passos-fluidos','Passos fluidos','água','maior',319,'Efeitos de Caminhar na Água, respiração aquática e natação igual ao deslocamento ou 4,5 m, o maior. Não confunda respirar água com imunidade a perigos ambientais.','Caminha e respira na água, com deslocamento de natação.')
    dom('ondulacoes-ondas','Ondulações e ondas','água','grandioso',319,'Sentido preciso de ondas 18 m e Empurrão Hidráulico de 5º círculo à vontade como magia inata. Duas ações de concentração, uma vez por dia: água rasa em emanação de 18 m por um minuto. Inimigos sem natação tratam como terreno difícil em movimento terrestre. Enquanto durar, seus efeitos de água podem se originar de qualquer ponto da emanação, além de alcance e área normais.','Sentido de ondas, magia à vontade e emanação que desloca origem de efeitos aquáticos.')
    assert sum(e.get('categoria')=='dom-reliquia' for e in d['equipamentos'])==72
